export const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

const prisma = new PrismaClient();

const buildWhyInterviewersAsk = (question: string, shortDescription: string) =>
  `Interviewers ask this to check whether you can choose and use AWS services based on real requirements rather than only recalling product names. ${shortDescription} A strong response should explain the decision, relevant security or reliability considerations, and the trade-offs involved.`;

const buildCommonMistakes = (question: string) => [
  `Naming an AWS service without explaining how it solves the problem in: ${question}`,
  "Ignoring IAM, least privilege, encryption, networking, or operational ownership.",
  "Skipping cost, availability, scaling, monitoring, and failure-mode considerations.",
];

async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "aws" },
    update: { name: "AWS", group: "Technology", description: "AWS cloud computing interview questions." },
    create: { name: "AWS", slug: "aws", group: "Technology", description: "AWS cloud computing interview questions." },
  });
  const subcategory = await prisma.subcategory.upsert({
    where: { categoryId_slug: { categoryId: category.id, slug: "aws" } },
    update: {},
    create: { name: "AWS", slug: "aws", categoryId: category.id },
  });

  for (let topicIndex = 0; topicIndex < topics.length; topicIndex += 1) {
    const [, question, slug, shortDescription, sampleAnswer] = topics[topicIndex];
    const commonMistakes = buildCommonMistakes(question);
    const followUpQuestions = [
      topics[(topicIndex + 1) % topics.length][1],
      topics[(topicIndex + 2) % topics.length][1],
      topics[(topicIndex + 3) % topics.length][1],
    ];
    const explanation = buildWhyInterviewersAsk(question, shortDescription);

    await prisma.interviewQuestion.upsert({
      where: { slug },
      update: {
        question,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation,
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: ["Explain the service or concept", "Connect it to a practical AWS requirement", "State the main trade-off"],
        commonMistakes,
        followUpQuestions,
        tags: ["aws", "cloud-computing"],
        isPublished: true,
      },
      create: {
        question,
        slug,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation,
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: ["Explain the service or concept", "Connect it to a practical AWS requirement", "State the main trade-off"],
        commonMistakes,
        followUpQuestions,
        tags: ["aws", "cloud-computing"],
        isPublished: true,
      },
    });
  }

  console.log(`Imported ${topics.length} AWS questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());